              import sailpoint.object.*;
              import java.util.*;
              import sailpoint.object.QueryOptions;
            	import sailpoint.object.Filter;

        			log.error("Account name in input is: "+accountName);
              QueryOptions qo = new QueryOptions();
              Filter f1 =Filter.eq("links.displayName",accountName);

              qo.add(f1); 
              List idn= context.getObjects(Identity.class, qo);
       		    String name1="";

        			if(idn != null && idn.size()==1)
								{
                  for(Identity id: idn)
                  {
                 // System.out.println("#From Search Owner :"+ id.getName());
                   name1= id.getName();
                  //System.out.println("#From Search Owner :"+ name1);
                  }	
                  return name1;
       				 }
             if(idn != null && idn.size()>1)
        				return "manyOwner";
           return "NoUserFound";

                //
                //System.out.println("############################################ :"+ ownerName);
                if(ownerName.equals("NoUserFound"))
                return "No Owner Found";
                if(ownerName.equals("manyOwner"))
                return "Multiple Owner Found";

			          return ownerName;
